import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"A tour of these docs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tour.md","filePath":"guide/tour.md"}'),s={name:"guide/tour.md"};function i(n,e,h,d,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="a-tour-of-these-docs" tabindex="-1">A tour of these docs <a class="header-anchor" href="#a-tour-of-these-docs" aria-label="Permalink to &quot;A tour of these docs&quot;">​</a></h1><p>Two minutes on how this site is organized and how to find things fast.</p><h2 id="the-three-areas" tabindex="-1">The three areas <a class="header-anchor" href="#the-three-areas" aria-label="Permalink to &quot;The three areas&quot;">​</a></h2><p><strong>Guide</strong> <em>(you are here)</em> — everything conceptual, in reading order. The sidebar mirrors the learning path:</p><ul><li><strong>Understand</strong> — what this runtime is, <a href="./architecture.html">how it boots</a>, and <a href="./native-bridge.html">how the native bridge works</a>. Read once, refer back rarely.</li><li><strong>Build</strong> — the hands-on part: <a href="./getting-started.html">set up a resource</a>, then <a href="./scripts.html">scripts</a>, <a href="./events.html">events</a>, <a href="./commands.html">commands</a>, and <a href="./exports.html">exports</a>. This is where you&#39;ll live at first.</li><li><strong>Runtime</strong> — the deeper mechanics you&#39;ll hit as your code grows: <a href="./threading.html">threading</a>, <a href="./natives.html">natives</a>, <a href="./entities.html">entities</a>, <a href="./serialization.html">serialization</a>.</li><li><strong>Reference</strong> — the <a href="./api-reference.html">API cheat sheet</a>, <a href="./gotchas.html">gotchas</a>, and the <a href="./migrating-from-lua.html">Lua migration guide</a>.</li></ul><p><strong>Client natives</strong> — all <strong>~7,600</strong> client natives, one page per game namespace (Ped, Vehicle, Graphics, Network, CFX, …). Each entry has the typed C# signature, a parameter table, the native hash, the Lua name, and a description where the community database has one.</p><p><strong>Server natives</strong> — the same treatment for the <strong>~379</strong> server-side natives (mostly the <code>CFX</code> namespace).</p><p><strong>Types</strong> — the generated listing of every public class, interface, struct and enum in the four runtime assemblies (<code>API</code>, <code>SharedAPI</code>, entity classes, pools, managers, attributes, formatters…), one page per C# namespace, with full member signatures. When the guide&#39;s prose isn&#39;t enough, <a href="/api/">the raw surface is here</a>.</p><h2 id="finding-a-native" tabindex="-1">Finding a native <a class="header-anchor" href="#finding-a-native" aria-label="Permalink to &quot;Finding a native&quot;">​</a></h2><p>Three ways, fastest first:</p><ol><li><strong>Search</strong> (press <code>/</code> or <code>Ctrl K</code>) — the search box indexes every native by its C# name. Searching the Lua name (<code>SET_ENTITY_COORDS</code>) works too, since it&#39;s on the page.</li><li><strong>Browse by namespace</strong> — open <a href="/natives/client/">Client natives</a> and pick the namespace from the sidebar. Counts are shown next to each.</li><li><strong>From code</strong> — if you have the C# method name, it&#39;s the heading on its namespace page; the URL anchor matches it exactly (e.g. <code>/natives/client/entity#SetEntityCoords</code>).</li></ol><p>Natives whose hash isn&#39;t in the public database are collected under <strong>Undocumented</strong> at the bottom of each sidebar — the signatures are still real (they come from the decompiled assembly), they just lack prose.</p><h2 id="suggested-reading-paths" tabindex="-1">Suggested reading paths <a class="header-anchor" href="#suggested-reading-paths" aria-label="Permalink to &quot;Suggested reading paths&quot;">​</a></h2><p><strong>&quot;I&#39;ve never written FiveM C# at all&quot;</strong><a href="./">Overview</a> → <a href="./getting-started.html">Creating a resource</a> → <a href="./scripts.html">Scripts</a> → <a href="./events.html">Events</a> → <a href="./threading.html">Threading</a>. That&#39;s a working, idiomatic resource.</p><p><strong>&quot;I write Lua and want to switch&quot;</strong><a href="./migrating-from-lua.html">Migrating from Lua</a> first — it maps every habit you have. Then <a href="./threading.html">Threading</a> (the <code>CreateThread</code> section) and <a href="./gotchas.html">Gotchas</a>.</p><p><strong>&quot;I know the old CitizenFX.Core / Mono runtime&quot;</strong> The comparison table on the <a href="./">Overview</a> is your index; the big deltas are <a href="./scripts.html">Scripts</a> (no <code>BaseScript</code>), <a href="./threading.html">Threading</a> (no <code>Tick +=</code>), and <a href="./serialization.html">Serialization</a> (MessagePack everywhere).</p><p><strong>&quot;Something&#39;s broken&quot;</strong><a href="./gotchas.html">Gotchas &amp; quirks</a>, then the troubleshooting table in <a href="./getting-started.html#troubleshooting">Creating a resource</a>.</p><h2 id="conventions-used-here" tabindex="-1">Conventions used here <a class="header-anchor" href="#conventions-used-here" aria-label="Permalink to &quot;Conventions used here&quot;">​</a></h2><ul><li><code>API.*</code> means the static facade of the side you&#39;re on (<code>CitizenFX.FiveM.Client.API</code> or <code>...Server.API</code>); <code>SharedAPI.*</code> works on both.</li><li>Code blocks labelled with a file path are complete, buildable examples; ones labelled &quot;shape&quot; or &quot;abridged&quot; are decompiled excerpts trimmed for reading.</li><li>Callout colors: green tips are recommendations, yellow warnings are sharp edges, red boxes are outright bugs or things that fail silently.</li><li>This is an <strong>unofficial</strong> reference reconstructed from one decompiled build (<code>net10test</code>, v1.0.0.0). Where your server&#39;s assemblies disagree with these pages, trust the assemblies.</li></ul>',19)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
